// Claude's review tests for A16 (search and fold in the Mocks tab). agy: do not edit this file.
import { expect, test, type Page } from '@playwright/test';
import { emptyState, type Mock, type Project, type SocketMock } from '../src/core/types';
import { type FixtureServer, startFixtureServer } from './fixture/server';
import { type WemockSession, launchWemock } from './helpers';

let fixture: FixtureServer;
let session: WemockSession;

test.beforeAll(async () => {
  fixture = await startFixtureServer();
  session = await launchWemock(fixture.url);
});

test.afterAll(async () => {
  await session?.context?.close();
  await fixture?.close();
});

function mock(id: string, method: Mock['method'], urlPattern: string, name?: string): Mock {
  return {
    id,
    ...(name ? { name } : {}),
    enabled: true,
    method,
    urlPattern,
    response: { status: 200, headers: {}, body: '', bodyEncoding: 'text', delayMs: 0 },
    source: 'manual',
    createdAt: 0,
  };
}

const hub: SocketMock = { id: 's1', name: 'Chat hub', enabled: true, kind: 'signalr', urlPattern: '/hubs/chat', onConnect: [], replies: [], createdAt: 0 };

function project(): Project {
  return {
    id: 'p1',
    name: 'site',
    origins: [fixture.origin],
    activeScenarioId: 'default',
    scenarios: [
      { id: 'default', name: 'Default', mocks: [mock('m1', 'GET', '/api/users', 'User list'), mock('m2', 'POST', '/api/orders')], sockets: [hub] },
      { id: 'a', name: 'Errors', mocks: [mock('m3', 'GET', '/api/users/:id', 'User 404'), mock('m4', 'DELETE', '/api/cart')] },
      { id: 'b', name: 'Empty', mocks: [] },
    ],
  };
}

async function openMocks(): Promise<{ page: Page; panel: Page; url: string }> {
  await session.setState({ ...emptyState(), enabledOrigins: [fixture.origin], projects: [project()] });
  const page = await session.context.newPage();
  await page.goto(`${fixture.url}/index.html`);
  const tabId = await session.tabIdOf(page);
  const panel = await session.context.newPage();
  const url = `chrome-extension://${session.extensionId}/panel.html?tabId=${tabId}`;
  await panel.goto(url);
  // Folds are kept in the panel's localStorage; start each test unfolded.
  await panel.evaluate(() => localStorage.removeItem('wemock.folded.p1'));
  await panel.reload();
  await panel.getByTestId('tab-mocks').click();
  await expect(panel.getByTestId('mock-row')).toHaveCount(4);
  return { page, panel, url };
}

function group(panel: Page, name: string) {
  return panel.locator('.scenario-group').filter({ has: panel.locator('.scenario-name-badge', { hasText: name }) });
}

test('the filter matches name, pattern and method, case-insensitively, and hides empty scenarios', async () => {
  const { page, panel } = await openMocks();
  try {
    const f = panel.getByTestId('mocks-filter');
    await f.fill('USER');
    await expect(panel.getByTestId('mock-row')).toHaveCount(2);
    await expect(panel.getByTestId('socket-row')).toHaveCount(0);
    await expect(panel.getByTestId('mocks-filter-count')).toHaveText('2 of 5');
    await expect(group(panel, 'Empty')).toHaveCount(0);
    await expect(group(panel, 'Default')).toHaveCount(1);

    await f.fill('/api/orders');
    await expect(panel.getByTestId('mock-row')).toHaveCount(1);
    await expect(group(panel, 'Errors')).toHaveCount(0);

    await f.fill('delete');
    await expect(panel.getByTestId('mock-row')).toHaveCount(1);
    await expect(panel.getByTestId('mock-row')).toContainText('/api/cart');

    await f.fill('chat');
    await expect(panel.getByTestId('mock-row')).toHaveCount(0);
    await expect(panel.getByTestId('socket-row')).toHaveCount(1);
    await expect(panel.getByTestId('mocks-filter-count')).toHaveText('1 of 5');

    // In the socket's name only, not its pattern.
    await f.fill('chat hub');
    await expect(panel.getByTestId('socket-row')).toHaveCount(1);

    await f.fill('nothing-like-this');
    await expect(panel.locator('.scenario-group')).toHaveCount(0);
    await expect(panel.getByTestId('mocks-filter-count')).toHaveText('0 of 5');

    await f.fill('');
    await expect(panel.getByTestId('mock-row')).toHaveCount(4);
    await expect(panel.locator('.scenario-group')).toHaveCount(3);
    await expect(panel.getByTestId('mocks-filter-count')).toHaveCount(0);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('a fold arrow hides a scenario’s rows and keeps its header', async () => {
  const { page, panel } = await openMocks();
  try {
    await group(panel, 'Default').getByTestId('scenario-fold').click();
    await expect(group(panel, 'Default')).toHaveCount(1);
    await expect(group(panel, 'Default').getByTestId('mock-row')).toHaveCount(0);
    await expect(group(panel, 'Default').getByTestId('socket-row')).toHaveCount(0);
    await expect(group(panel, 'Errors').getByTestId('mock-row')).toHaveCount(2);
    await expect(group(panel, 'Default').getByTestId('scenario-fold')).toHaveAttribute('aria-expanded', 'false');

    await group(panel, 'Default').getByTestId('scenario-fold').click();
    await expect(group(panel, 'Default').getByTestId('mock-row')).toHaveCount(2);
    await expect(group(panel, 'Default').getByTestId('scenario-fold')).toHaveAttribute('aria-expanded', 'true');
  } finally {
    await panel.close();
    await page.close();
  }
});

test('folding does not select the scenario', async () => {
  const { page, panel } = await openMocks();
  try {
    await group(panel, 'Default').click();
    await group(panel, 'Errors').getByTestId('scenario-fold').click();
    await expect(group(panel, 'Default')).toHaveClass(/selected/);
    await expect(group(panel, 'Errors')).not.toHaveClass(/selected/);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('the folded state survives reopening the panel', async () => {
  const { page, panel, url } = await openMocks();
  try {
    await group(panel, 'Errors').getByTestId('scenario-fold').click();
    await expect(group(panel, 'Errors').getByTestId('mock-row')).toHaveCount(0);
    // A new panel document, as DevTools makes each time it opens.
    const again = await session.context.newPage();
    try {
      await again.goto(url);
      await again.getByTestId('tab-mocks').click();
      await expect(group(again, 'Default').getByTestId('mock-row')).toHaveCount(2);
      await expect(group(again, 'Errors').getByTestId('mock-row')).toHaveCount(0);
    } finally {
      await again.close();
    }
  } finally {
    await panel.close();
    await page.close();
  }
});

test('a filter shows matches inside a folded scenario', async () => {
  const { page, panel } = await openMocks();
  try {
    await group(panel, 'Errors').getByTestId('scenario-fold').click();
    await panel.getByTestId('mocks-filter').fill('cart');
    await expect(group(panel, 'Errors').getByTestId('mock-row')).toHaveCount(1);
    await panel.getByTestId('mocks-filter').fill('');
    await expect(group(panel, 'Errors').getByTestId('mock-row')).toHaveCount(0);
  } finally {
    await panel.close();
    await page.close();
  }
});
